function downloadTemplate(type){
  type=type||'bids';const bin=atob(type==='bids'?IMPORT_TEMPLATE_B64:JOB_TEMPLATES[type]||DIR_TEMPLATES[type]);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
  const url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));
  const a=document.createElement('a');a.href=url;a.download=({bids:'Bid-Import-Template',clients:'Clients-Import-Template',vendors:'Vendors-Import-Template',jobbid:'Job-Budget-Bid-Items-Template',jobcc:'Job-Budget-Cost-Codes-Template',jobcost:'Job-Cost-Import-Template'}[type])+'.xlsx';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);
}
